# Generates test/scipy/test_stats_final_newdist.py with scipy 1.18.1.
import numpy as np, scipy.stats as st
def L(a): return repr([float(v) for v in np.ravel(a)])
xs = [-1.5, -0.2, 0.3, 1.1, 2.7]
qs = [0.05, 0.3, 0.5, 0.9]
o = ["# Copyright (C) 2026 the Typhon authors",
"# Expected values generated by test/scipy/gen_stats_final_newdist.py (scipy 1.18.1).",
"import numpy as np", "import scipy.stats as st", "",
"def close(a, b, rtol: float = 1e-7) -> bool:",
"    x = np.asarray(a).astype(float).ravel()", "    y = np.asarray(b).astype(float).ravel()",
"    if x.shape != y.shape:", "        return False",
"    for i in range(x.shape[0]):",
"        u = float(x[i])", "        v = float(y[i])",
"        if not (abs(u - v) <= 1e-9 + rtol * abs(v) or (u != u and v != v)):",
"            print('mismatch', i, u, v)", "            return False",
"    return True", "", f"xs = {xs}", f"qs = {qs}", ""]
def case(name, ctor_src, X, pos=False, disc=False):
    x = np.array([0.4, 1.3, 2.2, 3.1]) if pos else np.array(xs)
    if disc: x = np.array([0., 1., 3., 5., 8.])
    o.append("@test"); o.append(f"def test_{name}():"); o.append(f"    X = {ctor_src}")
    xl = L(x); 
    o.append(f"    x = {list(map(float, x))}")
    f = 'pmf' if disc else 'pdf'
    o.append(f"    assert close(X.{f}(x), {L(getattr(X, f)(x))})")
    o.append(f"    assert close(X.cdf(x), {L(X.cdf(x))})")
    o.append(f"    assert close(X.ccdf(x), {L(X.ccdf(x))})")
    o.append(f"    assert close(X.icdf(qs), {L(X.icdf(qs))})")
    o.append(f"    assert close([X.mean(), X.variance()], {L([X.mean(), X.variance()])}, 1e-6)")
    o.append("")
N = st.Normal(mu=0.5, sigma=1.5)
case('normal', "st.Normal(mu=0.5, sigma=1.5)", N)
case('uniform', "st.Uniform(a=-1.0, b=3.0)", st.Uniform(a=-1., b=3.))
case('logistic', "st.Logistic(mu=0.2, s=0.8)", st.Logistic(mu=0.2, s=0.8))
case('binomial', "st.Binomial(n=10, p=0.3)", st.Binomial(n=10, p=0.3), disc=True)
case('mixture', "st.Mixture([st.Normal(mu=-1.0, sigma=0.5), st.Uniform(a=0.0, b=2.0)], weights=[0.3, 0.7])",
     st.Mixture([st.Normal(mu=-1., sigma=.5), st.Uniform(a=0., b=2.)], weights=[.3, .7]))
case('truncate', "st.truncate(st.Normal(mu=0.5, sigma=1.5), -1.0, 2.0)", st.truncate(N, -1., 2.))
case('order', "st.order_statistic(st.Normal(mu=0.5, sigma=1.5), r=2, n=5)", st.order_statistic(N, r=2, n=5))
case('abs', "st.abs(st.Normal(mu=0.5, sigma=1.5))", st.abs(N), pos=True)
case('exp', "st.exp(st.Normal(mu=0.5, sigma=1.5))", st.exp(N), pos=True)
case('log', "st.log(st.exp(st.Normal(mu=0.5, sigma=1.5)))", st.log(st.exp(N)))
o += ["@test", "def test_sample():", "    X = st.Normal(mu=0.0, sigma=1.0)",
      "    s = X.sample(shape=(200,), rng=1)", "    assert s.shape == (200,)", "    assert abs(float(np.mean(s))) < 0.4"]
print("\n".join(o))
